console.log("EBS JavaScript loaded");
const headerToggle = document.querySelector(".header__toggle"),
  headerNav = document.querySelector(".header__nav"),
  headerLinks = document.querySelectorAll(".header__link");
(headerToggle &&
  headerNav &&
  (headerToggle.addEventListener("click", () => {
    const isExpanded = "true" === headerToggle.getAttribute("aria-expanded");
    (headerToggle.setAttribute("aria-expanded", String(!isExpanded)),
      headerNav.classList.toggle("active"));
  }),
  headerLinks.forEach((link) => {
    link.addEventListener("click", () => {
      (headerNav.classList.remove("active"),
        headerToggle.setAttribute("aria-expanded", "false"));
    });
  }),
  document.addEventListener("click", (event) => {
    const isClickInsideHeader =
      headerNav.contains(event.target) || headerToggle.contains(event.target);
    isClickInsideHeader ||
      (headerNav.classList.remove("active"),
      headerToggle.setAttribute("aria-expanded", "false"));
  }),
  window.addEventListener("resize", () => {
    window.innerWidth > 768 &&
      (headerNav.classList.remove("active"),
      headerToggle.setAttribute("aria-expanded", "false"));
  })),
  document.addEventListener("DOMContentLoaded", () => {
    const items = document.querySelectorAll(".services-details__item");
    if (!items.length) return;
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          entry.isIntersecting &&
            (entry.target.classList.add("is-visible"),
            observer.unobserve(entry.target));
        });
      },
      { threshold: 0.15, rootMargin: "0px 0px -60px 0px" },
    );
    items.forEach((item) => observer.observe(item));
  }));
const faqButtons = document.querySelectorAll(".faq__button");
faqButtons.length &&
  faqButtons.forEach((button) => {
    button.addEventListener("click", () => {
      const currentItem = button.closest(".faq__item");
      if (!currentItem) return;
      const currentAnswer = currentItem.querySelector(".faq__answer"),
        currentIcon = currentItem.querySelector(".faq__icon");
      if (!currentAnswer || !currentIcon) return;
      const isOpen = "true" === button.getAttribute("aria-expanded");
      (faqButtons.forEach((btn) => {
        const item = btn.closest(".faq__item");
        if (!item) return;
        const answer = item.querySelector(".faq__answer"),
          icon = item.querySelector(".faq__icon");
        answer &&
          icon &&
          (btn.setAttribute("aria-expanded", "false"),
          (answer.hidden = !0),
          item.classList.remove("faq__item--active"),
          (icon.textContent = "add"));
      }),
        isOpen ||
          (button.setAttribute("aria-expanded", "true"),
          (currentAnswer.hidden = !1),
          currentItem.classList.add("faq__item--active"),
          (currentIcon.textContent = "remove")));
    });
  });
const backToTop = document.querySelector("#bckToTop");
backToTop &&
  (window.addEventListener("scroll", () => {
    window.scrollY > 500
      ? backToTop.classList.add("show")
      : backToTop.classList.remove("show");
  }),
  backToTop.addEventListener("click", (event) => {
    (event.preventDefault(), window.scrollTo({ top: 0, behavior: "smooth" }));
  }));
const contactForm = document.querySelector("#contact-form");
if (contactForm) {
  const fullName = contactForm.querySelector("#full-name"),
    email = contactForm.querySelector("#email"),
    phone = contactForm.querySelector("#phone"),
    service = contactForm.querySelector("#service"),
    message = contactForm.querySelector("#message"),
    submitButton = contactForm.querySelector(".contact__button"),
    fields = [fullName, email, phone, service, message].filter(Boolean);
  function getErrorElement(field) {
    return document.querySelector(`#${field.id}-error`);
  }
  function clearError(field) {
    const error = getErrorElement(field);
    (field.classList.remove(
      "contact__input--error",
      "contact__select--error",
      "contact__textarea--error",
    ),
      field.setAttribute("aria-invalid", "false"),
      error && ((error.textContent = ""), (error.hidden = !0)));
  }
  function showError(field, message) {
    const error = getErrorElement(field);
    (field === service
      ? field.classList.add("contact__select--error")
      : field === message
        ? field.classList.add("contact__textarea--error")
        : field.classList.add("contact__input--error"),
      field.setAttribute("aria-invalid", "true"),
      error && ((error.textContent = message), (error.hidden = !1)));
  }
  function validateField(field) {
    const value = field.value.trim();
    if ((clearError(field), field === fullName)) {
      if (!value) return (showError(field, "Please enter your full name."), !1);
      if (value.length < 2)
        return (
          showError(field, "Your name must be at least 2 characters."),
          !1
        );
    }
    if (field === email) {
      if (!value)
        return (showError(field, "Please enter your email address."), !1);
      if (!field.validity.valid)
        return (showError(field, "Please enter a valid email address."), !1);
    }
    if (field === phone && value && !/^[+\d\s().-]{7,20}$/.test(value))
      return (showError(field, "Please enter a valid phone number."), !1);
    if (field === service && !value)
      return (showError(field, "Please select a service."), !1);
    if (field === message) {
      if (!value)
        return (showError(field, "Please tell us about your project."), !1);
      if (value.length < 10)
        return (showError(field, "Please provide at least 10 characters."), !1);
    }
    return !0;
  }
  (fields.forEach((field) => {
    (field.addEventListener("blur", () => {
      validateField(field);
    }),
      field.addEventListener("input", () => {
        "true" === field.getAttribute("aria-invalid") && validateField(field);
      }),
      field.addEventListener("change", () => {
        validateField(field);
      }));
  }),
    contactForm.addEventListener("submit", async (event) => {
      event.preventDefault();
      let formIsValid = !0,
        firstInvalidField = null;
      if (
        (fields.forEach((field) => {
          const valid = validateField(field);
          valid ||
            ((formIsValid = !1),
            firstInvalidField || (firstInvalidField = field));
        }),
        !formIsValid)
      )
        return void (firstInvalidField && firstInvalidField.focus());
      const originalButtonContent = submitButton.innerHTML;
      ((submitButton.disabled = !0),
        (submitButton.innerHTML = "\n    <span>Sending...</span>\n  "));
      try {
        const formData = new FormData(contactForm),
          response = await fetch("/", {
            method: "POST",
            headers: { "Content-Type": "application/x-www-form-urlencoded" },
            body: new URLSearchParams(formData).toString(),
          });
        if (response.ok) return void (window.location.href = "thank-you.html");
        throw new Error("Form submission failed.");
      } catch (error) {
        (console.error("Contact form error:", error),
          (submitButton.disabled = !1),
          (submitButton.innerHTML = originalButtonContent),
          alert("Sorry, your message could not be sent. Please try again."));
      }
    }));
}
